 ('request_rescue_scope','R5-S05.scope','申请限定救援门控检查'),('inspect_detention_records','R5-S05.records','现场核验扣押与返程资料'),('isolate_detention_drive','R5-S05.drive','隔离扣押门驱动'),('clear_duty_obstruction','R5-S05.obstruction','清理值守厅阻碍'),('begin_guard_group_encounter','R5-S06.guard','实际处置北站看守组'),('inspect_detention_door','R5-S06.door','检查实体扣押门'),('release_mara','R5-S06.release','机械开门与直接接触玛拉'),('open_inner_evacuation','R5-S06.return_bolt','内侧开启既有撤离闩'),('inspect_inner_evacuation','R5-S06.return_check','检查内侧撤离路径'),('receive_mara','R5-S02.reception','接收实际护送回来的导师'),('submit_rescue_instruction','R5-S02.reception','交接实际救援结果'),
