 ('choose_temporary_custody','R5-S07.custody','确认有限原件保管与公开'),('accept_joint_supervision','R5-S07.custody','逐岗接受共同监督'),('request_tower_takeover','R5-S07.custody','签发当地有限接管工作许可'),('isolate_archive_relay','R5-S08.control','隔离归档继电驱动'),('secure_archive_rack','R5-S08.rack','固定原件保存机架'),('begin_archive_relay_encounter','R5-S08.relay','处置独立归档继电防卫'),('configure_archive_load','R5-S08.control','配置保护三保存一复制零'),('appoint_archive_operator','R5-S08.duty','明确实际当地操作岗位'),('test_archive_configuration','R5-S08.load_test','核验当前版本配置'),('verify_archive_safety','R5-S08.load_test','提交当前有限安全来源'),('record_tower_future_requirements','R5-S08.load_test','发布仍需实际工作准备清单'),('inspect_archive_return','R5-S08.return_check','检查塔站返程'),('preserve_original_case','R5-S07.custody','交接唯一原件箱'),('send_transfer_demand','R5-S08.handover','记录鲁克实际拒交及转第七塔'),('submit_joint_handover','R5-S08.handover','提交塔站及临时共同处置授权'),
