questions=[dict(id='R5-QN-'+str(i).zfill(2),material_ref=m,prompt_en=en,prompt_zh=zh,kind='source_bounded_explanation',assessment='unassessed_no_band_score') for i,(m,en,zh) in enumerate(question_specs,1)]

